/**
 * Portfolio structure shared by every locale: stable ids, image paths and
 * grid placement. Display strings (titles, labels, alt text) live in the
 * i18n dictionaries and are matched by `slug` / `id`.
 */

export type CategoryId = "all" | "branding" | "social" | "dev" | "photo" | "video";

export const categoryIds: Exclude<CategoryId, "all">[] = [
  "branding",
  "social",
  "dev",
  "photo",
  "video",
];

export type Project = {
  slug: string;
  /** Grid presentation — localized type stays "wide" aware via className. */
  image: string;
  secondaryImage: string;
  categoryId: Exclude<CategoryId, "all">;
  className: string;
};

export const projects: Project[] = [
  {
    slug: "desert-notes",
    image: "/images/concept-desert.svg",
    secondaryImage: "/images/concept-color.svg",
    categoryId: "branding",
    className: "project-card--wide",
  },
  {
    slug: "skin-simply",
    image: "/images/concept-skin.svg",
    secondaryImage: "/images/concept-desert.svg",
    categoryId: "photo",
    className: "",
  },
  {
    slug: "color-in-motion",
    image: "/images/concept-color.svg",
    secondaryImage: "/images/concept-digital.svg",
    categoryId: "social",
    className: "",
  },
  {
    slug: "fresh-perspective",
    image: "/images/concept-digital.svg",
    secondaryImage: "/images/concept-skin.svg",
    categoryId: "dev",
    className: "",
  },
];

export const categoryOrder: CategoryId[] = ["all", ...categoryIds];

export function projectPath(slug: string): string {
  return `/projects/${slug}`;
}

export function getProject(slug: string): Project | undefined {
  return projects.find((project) => project.slug === slug);
}
